        padding: '2rem',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)',
        color: '#e8e8e8',
      }}
    >
      <div
        style={{
          textAlign: 'center',
          maxWidth: '28rem',
        }}
      >
        <div
          style={{
            fontSize: '4rem',
            fontWeight: 700,
            color: '#e94560',
            marginBottom: '0.5rem',
            letterSpacing: '-0.02em',
          }}
        >
          403
        </div>
        <h1
          style={{
            fontSize: '1.5rem',
            fontWeight: 600,
            marginBottom: '0.75rem',
          }}
        >
          Access Forbidden
        </h1>
        <p
          style={{
            color: '#a0a0a0',
            lineHeight: 1.6,
            marginBottom: '2rem',
          }}
        >
